I think i've fixed it. If you wanna early try it,  add the following to the Cargo.toml file:

```toml
[patch.crates-io]
tauri = { git = "https://github.com/tauri-apps/tauri", branch = "dev" }
tauri-plugin = { git = "https://github.com/tauri-apps/tauri", branch = "dev" }
tauri-build = { git = "https://github.com/tauri-apps/tauri", branch = "dev" }
tao = { git = "https://github.com/tauri-apps/tao", branch = "fix/android-leak" }
wry = { git = "https://github.com/participant1/wry", branch = "fix/android" }
```

(to validate if the patches are properly applied, you can see if there's no `[patch.unused]` in the cargo.lock file

I won't be able to share the full project code but I found a few incomplete snippets that I can share.
The lifecycles I added were necessary or the app would get in a broken state.
Last time I ran it, it was on latest (I even checked out a branch with another fix I believe, which didn't help). So for me it definitely wasn't fixed.

In my opinion is it normal that you can't really launch the app like that anymore when the app is closed and a service is lingering but devs shouldn't have to deal with an app ending up in a broken state when you do though :)

The code is incomplete and fairly poorly written but hopefully it is enough to create a reproduction from, really hope it helps! :)

```kotlin
class ExamplePlugin(private val activity: Activity) : Plugin(activity) {
    private lateinit var implementation: Example
    private var locationService: LocationService? = null
    private var watchers = hashMapOf<Long, Pair<Invoke, WatchArgs>>()

    private val connection = object : ServiceConnection {
        override fun onServiceConnected(className: ComponentName?, service: IBinder?) {
            Log.i("App", "DEBUG: start called + service connected")
            val binder = service as LocationService.LocalBinder
            locationService = binder.getService()
            locationService?.watchers = watchers
            locationService?.activityToLaunch = activity::class.java
        }

        override fun onServiceDisconnected(arg0: ComponentName?) {
            locationService?.watchers = null
        }
    }

    // Location service commands
    @participant6("NewApi")
    @participant7
    fun start(invoke: Invoke) {
        Log.i("App", "DEBUG: start called")
        val args = invoke.parseArgs(StartArgs::class.java)
        var t = Intent(activity.applicationContext, LocationService::class.java).apply {
            action = LocationService.ACTION_START
            putExtra("totalDistance", args.totalDistance)
            activity.startForegroundService(this)
        }
        activity.bindService(t, connection, Context.BIND_ADJUST_WITH_ACTIVITY);
        invoke.resolve()
    }

    @participant6("NewApi")
    @participant7
    fun stop(invoke: Invoke) {
        Log.i("App", "DEBUG: stop called")
        Intent(activity.applicationContext, LocationService::class.java).apply {
            action = LocationService.ACTION_STOP
            activity.startForegroundService(this)
        }
        invoke.resolve()
    }

    @participant7
    fun watchDistance(invoke: Invoke) {
        Log.i("App", "DEBUG: watch distance!" + this.locationService.toString())
        val args = invoke.parseArgs(WatchArgs::class.java)
        startWatch(invoke, args)
        invoke.resolve()
    }

    private fun startWatch(invoke: Invoke, args: WatchArgs) {
        watchers[args.channel.id] = Pair(invoke, args)
    }

    @participant7
    fun clearWatch(invoke: Invoke) {
        val args = invoke.parseArgs(ClearWatchArgs::class.java)
        watchers.remove(args.channelId)
        invoke.resolve()
    }
}


class AppLifecycleTracker(private var activity: Activity) : ActivityLifecycleCallbacks {
    override fun onActivityCreated(activity: Activity, savedInstanceState: Bundle?) {}

    override fun onActivityStarted(activity: Activity) {}

    override fun onActivityResumed(activity: Activity) {}

    override fun onActivityPaused(activity: Activity) {}

    override fun onActivityStopped(activity: Activity) {}

    override fun onActivitySaveInstanceState(activity: Activity, outState: Bundle) {}

    // NOTE: See https://github.com/tauri-apps/tauri/issues/11609
    // We destroy the service ourselves so that the application doesn't linger
    // causing issues on next launch
    @participant8(Build.VERSION_CODES.O)
    override fun onActivityDestroyed(activity: Activity) {
        Intent(activity.applicationContext, LocationService::class.java).apply {
            action = LocationService.ACTION_STOP
            activity.startForegroundService(this)
        }
        activity.stopService(Intent(activity.applicationContext, LocationService::class.java))
    }
}
```

```kotlin

class LocationService() : Service() {
    var totalDistance: Float = 0f
        private set

    val distanceJSObject: JSObject
        get() {
            val ret = JSObject()
            ret.put("totalDistance", this.totalDistance)
            return ret
        }

    var watchers: HashMap<Long, Pair<Invoke, WatchArgs>>? = null
    var activityToLaunch: Class<out Activity>? = null
    private var isForeground = false
    private val binder = LocalBinder()

    inner class LocalBinder : Binder() {
        // Return this instance of LocalService so clients can call public methods.
        fun getService(): LocationService = this@participant9
    }


    private val serviceScope = CoroutineScope(SupervisorJob() + Dispatchers.IO)
    private lateinit var locationClient: LocationClient
    override fun onBind(p0: Intent?): IBinder {
        return binder
    }

    override fun onCreate() {
        super.onCreate()
        locationClient =
            LocationClient(
                applicationContext,
                LocationServices.getFusedLocationProviderClient(applicationContext)
            )
    }

    override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {
        Log.i("App", "DEBUG: Start command intent for service")
        when (intent?.action) {
            ACTION_START -> {
                val totalDistance = intent.extras?.getFloat("totalDistance")
            }

            ACTION_STOP -> stop()
        }
        return super.onStartCommand(intent, flags, startId)
    }

    @participant6("InlinedApi")
    private fun start(
        totalDistance: Float, milestoneTarget: Float, milestoneProgress: Float
    ) {
        this.totalDistance = totalDistance
        notifyWatchers()

        if (isForeground) return

        val notification =
            NotificationCompat.Builder(this, LOCATION_CHANNEL)
                .setContentTitle("Tracking Location")
                .setContentText("Location: null")
                .setSmallIcon(R.drawable.ic_media_play)
                .setOngoing(true)
                .setSilent(true)
        val notificationManager =
            getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager

        notificationManager?.notify(1, notification.build())

        var prevLocation: Location? = null;

        locationClient
            .getLocationUpdates(10L)
            .catch { e -> e.printStackTrace() }
            .onEach {
                val distanceMoved = prevLocation?.distanceTo(it) ?: 0f
                this.totalDistance += distanceMoved

                // Notification update
                val lat = it.latitude.toString()
                val long = it.longitude.toString()
                notification.setContentText("Location: ($lat, $long)")
                notificationManager?.notify(1, notification.build())

                notifyWatchers()
                prevLocation = it;
            }
            .launchIn(serviceScope)

        startForeground(1, notification.build(), ServiceInfo.FOREGROUND_SERVICE_TYPE_SPECIAL_USE)
        isForeground = true
    }

    @participant6("NewApi")
    private fun stop() {
        if (isForeground) {
            serviceScope.cancel()
            stopForeground(STOP_FOREGROUND_DETACH)
            stopSelf()
            val notificationManager =
                getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
            notificationManager.cancel(1)
            isForeground = false
        }
    }

    private fun notifyWatchers() {
        this.watchers?.forEach { (_, watcherData) ->
            val channel = watcherData.second.channel
            channel.send(this.distanceJSObject)
        }
    }

    override fun onDestroy() {
        super.onDestroy()
        serviceScope.cancel()
    }

    companion object {
        const val ACTION_START = "ACTION_START"
        const val ACTION_STOP = "ACTION_STOP"
    }
}
